def showcase(lang,url):
 x=COPY[lang];panels=[]
 for i in range(4):
  state=' hidden' if i else ''
  source=''.join('<span>'+e(v)+'</span>' for v in x['sources'][i])
  tasks=''.join('<li><span class="system-step">'+str(j+1).zfill(2)+'</span><span>'+e(v)+'</span><i aria-hidden="true"></i></li>' for j,v in enumerate(x['tasks'][i]))
  slug=['solutions/document-processing','solutions/sales-operations','solutions/customer-support','solutions/technical-operations'][i]
  panels.append('<div class="system-panel" role="tabpanel" id="system-panel-'+str(i)+'" aria-labelledby="system-tab-'+str(i)+'" tabindex="0"'+state+'><div class="system-summary"><span class="eyebrow">0'+str(i+1)+'</span><h3>'+e(x['names'][i])+'</h3><p>'+e(x['descriptions'][i])+'</p><a class="textlink" href="'+url(lang,slug)+'">'+e(x['more'])+'</a></div><div class="system-workspace"><div class="system-workspace-bar"><b>'+e(x['workspace'])+'</b><span>'+e(x['tag'])+'</span></div><div class="system-sources"><span>'+e(x['source'])+'</span>'+source+'</div><div class="system-work"><span class="eyebrow">'+e(x['work'])+'</span><ol>'+tasks+'</ol></div><div class="system-result"><span class="eyebrow">'+e(x['output'])+'</span><p>'+e(x['results'][i])+'</p></div><details class="system-review"><summary>'+e(x['approval'])+'</summary><p>'+e(x['reviews'][i])+'</p></details></div></div>')
 return '<section class="sec ai-brand-section" id="systems"><div class="wrap"><div class="sec-h"><span class="eyebrow">'+e(x['eyebrow'])+'</span><h2>'+e(x['title'])+'</h2><p class="lead">'+e(x['lead'])+'</p></div><div data-system-showcase><div class="system-tabs" role="tablist" aria-label="'+e(x['title'])+'">'+''.join('<button type="button" role="tab" id="system-tab-'+str(i)+'" aria-controls="system-panel-'+str(i)+'" aria-selected="'+('true' if i==0 else 'false')+'" tabindex="'+('0' if i==0 else '-1')+'">'+e(t)+'</button>' for i,t in enumerate(x['tabs']))+'</div>'+''.join(panels)+'</div></div></section>'

def custom(lang,url):
 x=COPY[lang]
 return '<section class="sec ai-brand-section"><div class="wrap"><div class="custom-build"><div class="sec-h"><span class="eyebrow">'+e(x['customEyebrow'])+'</span><h2>'+e(x['customTitle'])+'</h2><p class="lead">'+e(x['customBody'])+'</p></div><div class="custom-controls">'+''.join('<div><span>0'+str(i+1)+'</span><h3>'+e(t)+'</h3><p>'+e(b)+'</p></div>' for i,(t,b) in enumerate(x['controls']))+'</div><div class="custom-tools"><h3>'+e(x['tools'])+'</h3><p>'+e(x['toolsBody'])+'</p></div><div class="acts"><a class="btn btn-p" href="'+url(lang,'project-intake')+'">'+e(x['customCta'])+'</a><a class="btn btn-g" href="'+url(lang,'security-deployment')+'">'+e(x['securityCta'])+'</a></div></div></div></section>'
